export const MARKET_STALLS_REGISTRY: MarketStallInfo[] = RAW_STALLS.map((t) => ({
  stallNumber: t[0],
  section: t[1],
  subSection: t[2],
  holderName: t[3],
  area: t[4],
  rate2025: t[5],
  rate2026: t[6],
  rate2027: t[7],
  rate2028: t[8],
}));

// Fast lookup map by normalized stall number
const normalizedMap = new Map<string, MarketStallInfo>();

// Build lookup map
MARKET_STALLS_REGISTRY.forEach((stall) => {
  const key = normalizeStallKey(stall.stallNumber);
  if (!normalizedMap.has(key)) {
    normalizedMap.set(key, stall);
  }
});

/**
 * Normalize stall number for flexible matching
 * e.g. "I 1A1" -> "I1A1", "vs-001" -> "VS001", "VS 001" -> "VS001"
 */
export function normalizeStallKey(str: string): string {
  return (str || '')
    .toUpperCase()
    .replace(/[^A-Z0-9]/g, '');
}

/**
 * Find a stall by number with fuzzy / flexible normalization
 */
export function findStallByNumber(query: string): MarketStallInfo | null {
  if (!query || !query.trim()) return null;
  const key = normalizeStallKey(query);
  if (normalizedMap.has(key)) {
    return normalizedMap.get(key)!;
  }

  // Also check without leading zeros (e.g. VS001 -> VS1)
  const strippedZeros = key.replace(/([A-Z]+)0+(\d+)/, '$1$2');
  if (normalizedMap.has(strippedZeros)) {
    return normalizedMap.get(strippedZeros)!;
  }

  // Also check with leading zeros (e.g. VS1 -> VS001 or VS01)
  const zeroPadded2 = key.replace(/([A-Z]+)(\d{1,2})$/, (_, prefix, num) => prefix + num.padStart(2, '0'));
  if (normalizedMap.has(zeroPadded2)) {
    return normalizedMap.get(zeroPadded2)!;
  }
  const zeroPadded3 = key.replace(/([A-Z]+)(\d{1,2})$/, (_, prefix, num) => prefix + num.padStart(3, '0'));
  if (normalizedMap.has(zeroPadded3)) {
    return normalizedMap.get(zeroPadded3)!;
  }

  return null;
}

/**
 * Search stalls for autocomplete suggestions
 */
export function searchStalls(query: string, limit = 8): MarketStallInfo[] {
  if (!query || !query.trim()) return [];
  const q = normalizeStallKey(query);
  if (!q) return [];

  const results: MarketStallInfo[] = [];
  for (const stall of MARKET_STALLS_REGISTRY) {
    const key = normalizeStallKey(stall.stallNumber);
    if (key.startsWith(q) || key.includes(q)) {
      results.push(stall);
      if (results.length >= limit) break;
    }
  }
  return results;
}
